"""Pipeline wiring.

Secret: the order in which the stages run (alias split, lex, rewrite,
extract globals, load config, expand aliases, resolve, bind, run or hand
off to a remote transport) and how failures map to output and exit codes.
"""

import os
import time

from . import (aliases, binding, catalog, config_files, db, dispatch, file_cache,
               help_text, logfile, process, remote, rewrites, runtime_config,
               tokens, values)
from .command_tree import CommandTree
from .errors import CliError, Halt, MissingPositional
from .output import Output, color_enabled

_COMPLETION = ["cli", "completion"]


class CommandContext:
    """Everything a command handler may use."""

    def __init__(self, command, args, out, config, tree, cwd=None, cache=None,
                 launcher=None, db=None, env=None):
        self.command = command
        self.args = args
        self.out = out
        self.config = config
        self.tree = tree
        self.cwd = cwd if cwd is not None else os.getcwd()
        self.cache = cache
        self.launcher = launcher
        self.db = db
        self.env = dict(env) if env is not None else dict(os.environ)

    def run_process(self, command, **kwargs):
        """Run an external command (see ``process.run``)."""
        kwargs.setdefault("out", self.out)
        kwargs.setdefault("cwd", self.cwd)
        return process.run(command, **kwargs)

    def launch_self(self, command, *args, **kwargs):
        """Re-dispatch an appctl command in a child process (see
        ``process.Launcher.launch_self``)."""
        return self.launcher.launch_self(command, *args, **kwargs)

    def runcommand(self, command, **kwargs):
        """Run an appctl command in a child process and return its output
        (see ``process.Launcher.runcommand``)."""
        return self.launcher.runcommand(command, **kwargs)

    def read_value(self, index):
        """Positional ``index``, or STDIN when it was not given, decoded
        according to ``--format``; ``None`` when neither is available."""
        raw = self.args.positional(index)
        if raw is None:
            raw = self.out.read_stdin()
            if raw is None:
                return None
        return values.read_value(raw, self.args.option("format"))


def build_tree():
    tree = CommandTree()
    catalog.register_all(tree)
    return tree


def _split_alias(argv):
    """Remove a leading ``@alias`` word; return ``(alias, argv)``."""
    for index, raw in enumerate(argv):
        if raw == "--":
            break
        if raw.startswith("--") and len(raw) > 2:
            continue
        if aliases.is_alias_name(raw):
            return raw, argv[:index] + argv[index + 1:]
        break
    return None, argv


def _is_completion(argv):
    """Tab-completion invocations are never written to the log file."""
    words = []
    for raw in argv:
        if raw == "--":
            break
        if not raw.startswith("--"):
            words.append(raw)
    return words[:len(_COMPLETION)] == _COMPLETION


def _last_option(options, name):
    found = None
    for key, value in options:
        if key == name:
            found = value
    return found


class _Invocation:
    def __init__(self, argv, env, stdout, stderr, tree, cwd, stdin, started):
        self.argv = argv
        self.env = env
        self.stdout = stdout
        self.stderr = stderr
        self.tree = tree
        self.cwd = cwd
        self.stdin = stdin
        self.started = started

    def _color(self, setting):
        return color_enabled(setting, self.stdout)

    def start(self, alias):
        self.locations = config_files.Locations(self.env)
        log = logfile.LogFile(logfile.log_path(self.locations.root_dir),
                              enabled=not _is_completion(self.argv))
        log.start_invocation()
        self.out = out = Output(self.stdout, self.stderr, stdin=self.stdin, log=log,
                                start=self.started, color=self._color("auto"))
        try:
            items = rewrites.apply(tokens.lex(self.argv))
            self.runtime, self.items = runtime_config.extract(items, self.env)
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        runtime_values = self.runtime.values
        out.configure(quiet=self.runtime.quiet(),
                      debug=runtime_values.get("debug", False),
                      color=self._color(runtime_values.get("color", "auto")))
        for warning in self.runtime.warnings:
            out.warning(warning)
        self.cache = file_cache.from_env(self.env, self.locations.root_dir,
                                         warn=out.warning)
        try:
            self.db = db.open_database(self.locations.root_dir)
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        try:
            return self.load_and_execute(alias)
        finally:
            self.db.close()
            if not _is_completion(self.argv):
                try:
                    self.cache.clean()
                except OSError:
                    pass

    def load_and_execute(self, alias):
        out = self.out
        try:
            self.loaded = config_files.load(self.locations, self.cwd)
            if "color" not in self.runtime.values:
                out.configure(color=self._color(self.loaded.values.get("color", "auto")))
            self.registry = aliases.AliasRegistry(
                self.loaded.aliases, aliases.runtime_aliases(self.env))
            for path in self.loaded.files:
                out.debug(f"Loaded config file: {path}", group="bootstrap")
            return self.execute(alias, ())
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        except Halt as exc:
            return exc.exit_code

    def execute(self, alias, stack):
        if alias is None:
            return self.invoke({})
        target = self.registry.resolve(alias)
        if not target.is_group():
            return self.invoke(target.connection)
        code = 0
        for member in target.members:
            if member == alias or member in stack:
                continue
            self.out.log(member)
            try:
                result = self.execute(member, stack + (alias,))
            except CliError as exc:
                self.out.report(exc)
                result = exc.exit_code
            code = result or code
        return code

    def invoke(self, connection):
        config = runtime_config.layer(
            self.runtime, self.loaded.values, connection,
            locations=self.locations, loaded=self.loaded, aliases=self.registry)
        self.out.configure(color=self._color(config.color()))
        if config.ssh():
            return remote.run(config.ssh(), self.argv, connection,
                              self.runtime.values, config, self.env, self.out,
                              self.stdout, self.stderr)
        return self.run_local(config)

    def run_local(self, config):
        out = self.out
        if self.tree is None:
            self.tree = build_tree()
        tree = self.tree
        items = self.items
        words = [t.text for t in items if not t.is_option()] or ["help"]
        options = [(t.name, t.value) for t in items if t.is_option()]
        node = None
        try:
            node, remaining = dispatch.resolve(tree, words, config.disabled_commands())
            out.debug(f"Resolved command '{node.path}' with arguments {remaining}",
                      group="bootstrap")
            out.log_only(f"Command: {node.path}")
            if not node.is_runnable():
                out.usage(help_text.composite_usage(node))
                return 0
            remaining = self.stdin_fallback(node.synopsis, remaining, options)
            bound = binding.bind(node.path, node.synopsis, node.defaults(),
                                 remaining, options)
            launcher = process.Launcher(
                self.runtime.values, self.env, self.cwd, out,
                config_path=self.locations.global_config_path)
            result = node.run(CommandContext(node, bound, out, config, tree,
                                             cwd=self.cwd, cache=self.cache,
                                             launcher=launcher, db=self.db,
                                             env=self.env))
            return int(result or 0)
        except MissingPositional:
            out.usage(help_text.usage_line(node))
            return 1

    def stdin_fallback(self, synopsis, words, options):
        """Read a missing required positional from STDIN, if any is piped."""
        if len(words) >= synopsis.required_positional_count():
            return words
        raw = self.out.read_stdin()
        if raw is None:
            return words
        fmt = (_last_option(options, "format")
               if "format" in synopsis.option_names() else None)
        return list(words) + [values.read_value(raw, fmt)]


def run(argv, env, stdout, stderr, tree=None, cwd=None, stdin=None):
    """Run one invocation and return its exit code.

    ``stdin`` defaults to ``sys.stdin`` at the time input is needed.
    """
    started = time.monotonic()
    alias, argv = _split_alias(list(argv))
    invocation = _Invocation(argv, env, stdout, stderr, tree,
                             cwd if cwd is not None else os.getcwd(), stdin, started)
    return invocation.start(alias)
"""Command resolution.

Secret: how positional words are walked down the command tree, and when
leftover words become arguments of the matched command rather than unknown
subcommands.
"""

from . import messages as _messages
from .errors import CliError
from .suggest import suggest


def resolve(tree, words, disabled=()):
    """Find the deepest command matching the leading ``words``.

    Returns ``(node, remaining_words)``. Raises ``CliError`` for an unknown
    top-level command, an unknown subcommand under a group that cannot
    itself run, or a command whose path is listed in ``disabled``.
    """
    disabled = set(disabled)
    node = tree.root
    words = list(words)
    consumed = 0
    for word in words:
        if not node.has_children():
            break
        child = node.find_child(word)
        if child is None:
            if node.is_runnable() and not node.is_root():
                break
            suggestion = suggest(word, node.child_names())
            if node.is_root():
                raise CliError(_messages.unregistered_command(word, suggestion))
            raise CliError(_messages.unregistered_subcommand(
                word, node.path, suggestion))
        node = child
        consumed += 1
        if node.path in disabled:
            raise CliError(_messages.command_disabled(node.path))
    return node, words[consumed:]
"""Exception types shared by several module interfaces."""


class CliError(Exception):
    """A user-facing failure: the message is reported as an error and the
    process exits with ``exit_code``.

    ``message`` may be a list of lines, which is reported as a multi-line
    error. A ``sensitive`` error contains user-supplied material that must
    never reach the log file; ``log_message`` is an optional redacted form
    that may be logged instead.
    """

    def __init__(self, message, exit_code=1, sensitive=False, log_message=None):
        lines = None
        if isinstance(message, (list, tuple)):
            lines = [str(line) for line in message]
            message = "\n".join(lines)
        super().__init__(message)
        self.message = message
        self.lines = lines
        self.exit_code = exit_code
        self.sensitive = sensitive
        self.log_message = log_message


class MissingPositional(Exception):
    """Raised when a command did not receive all of its required positional
    arguments; the caller is expected to show that command's usage."""


class Halt(Exception):
    """Stops the invocation with ``exit_code`` without reporting anything
    (the cause has already been shown, e.g. by a child process)."""

    def __init__(self, exit_code):
        super().__init__(exit_code)
        self.exit_code = exit_code
"""Persistent state database.

Secret: where the SQLite file lives, the table layout used for key/value
options and for the migration history, the timestamp format, and how
connection and schema failures are reported.
"""

import os
import sqlite3
from datetime import datetime, timezone

from . import messages
from .errors import CliError

_SUBDIR = "db"
_FILE_NAME = "appctl.sqlite"
_TIMESTAMP = "%Y-%m-%dT%H:%M:%SZ"
_BUSY_TIMEOUT = 30

_SCHEMA = (
    """CREATE TABLE IF NOT EXISTS options (
        key TEXT NOT NULL PRIMARY KEY,
        value TEXT NOT NULL,
        modified_on TEXT NOT NULL
    )""",
    """CREATE TABLE IF NOT EXISTS migrations (
        migration TEXT NOT NULL,
        type TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        PRIMARY KEY (migration, type)
    )""",
)


def db_dir(root_dir):
    return os.path.join(root_dir, _SUBDIR)


def db_path(root_dir):
    """``<root_dir>/db/appctl.sqlite``."""
    return os.path.join(db_dir(root_dir), _FILE_NAME)


def timestamp(now=None):
    """UTC timestamp in ISO 8601 form, e.g. ``2026-01-02T03:04:05Z``."""
    now = now or datetime.now(timezone.utc)
    return now.astimezone(timezone.utc).strftime(_TIMESTAMP)


def _details(exc):
    if isinstance(exc, OSError):
        return getattr(exc, "strerror", None) or str(exc)
    return str(exc)


def _text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="surrogateescape")
    if isinstance(value, bool):
        return "true" if value else "false"
    return "" if value is None else str(value)


class Database:
    """Key/value options and migration history kept in a SQLite file.

    The file and its tables are created on first access. Failures raise a
    ``CliError`` carrying the user-facing message.
    """

    def __init__(self, path):
        self.path = str(path)
        self._conn = None
        self._connect()
        self._create_tables()

    # --- setup ------------------------------------------------------------

    def _connect(self):
        try:
            directory = os.path.dirname(self.path)
            if directory and not os.path.isdir(directory):
                os.makedirs(directory, exist_ok=True)
            self._conn = sqlite3.connect(self.path, timeout=_BUSY_TIMEOUT,
                                         isolation_level=None)
        except (OSError, sqlite3.Error) as exc:
            raise CliError(messages.db_connection_failed(_details(exc))) from exc

    def _create_tables(self):
        try:
            with self._transaction():
                for statement in _SCHEMA:
                    self._conn.execute(statement)
        except sqlite3.Error as exc:
            self.close()
            raise CliError(messages.db_table_creation_failed(_details(exc))) from exc

    def _transaction(self):
        return _Transaction(self._conn)

    def close(self):
        if self._conn is not None:
            try:
                self._conn.close()
            except sqlite3.Error:
                pass
            self._conn = None

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()

    # --- options ----------------------------------------------------------

    def get_option(self, key):
        """The stored string for ``key``, or ``False`` when it is not set."""
        row = self._conn.execute("SELECT value FROM options WHERE key = ?",
                                 (_text(key),)).fetchone()
        return False if row is None else _text(row[0])

    def update_option(self, key, value):
        """Insert or replace the value stored under ``key``."""
        with self._transaction():
            self._conn.execute(
                "INSERT INTO options (key, value, modified_on) VALUES (?, ?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value = excluded.value, "
                "modified_on = excluded.modified_on",
                (_text(key), _text(value), timestamp()))
        return True

    def get_options(self):
        """Every option as ``{key, value, modified_on}``, ordered by key."""
        rows = self._conn.execute(
            "SELECT key, value, modified_on FROM options ORDER BY key")
        return [{"key": _text(k), "value": _text(v), "modified_on": _text(m)}
                for k, v, m in rows]

    # --- migrations -------------------------------------------------------

    def get_migrations(self, migration_type=None):
        """Applied migrations as ``{migration, type, timestamp}``, ordered by
        type and then name; optionally only those of ``migration_type``."""
        query = "SELECT migration, type, timestamp FROM migrations"
        params = ()
        if migration_type is not None:
            query += " WHERE type = ?"
            params = (_text(migration_type),)
        query += " ORDER BY type, migration"
        return [{"migration": _text(m), "type": _text(t), "timestamp": _text(s)}
                for m, t, s in self._conn.execute(query, params)]

    def is_migrated(self, migration, migration_type):
        row = self._conn.execute(
            "SELECT 1 FROM migrations WHERE migration = ? AND type = ?",
            (_text(migration), _text(migration_type))).fetchone()
        return row is not None

    def add_migration(self, migration, migration_type):
        """Record ``migration`` as applied now."""
        with self._transaction():
            self._conn.execute(
                "INSERT INTO migrations (migration, type, timestamp) VALUES (?, ?, ?) "
                "ON CONFLICT(migration, type) DO UPDATE SET timestamp = excluded.timestamp",
                (_text(migration), _text(migration_type), timestamp()))
        return True

    def remove_migration(self, migration, migration_type):
        """Forget ``migration``; ``True`` when a record was removed."""
        with self._transaction():
            cursor = self._conn.execute(
                "DELETE FROM migrations WHERE migration = ? AND type = ?",
                (_text(migration), _text(migration_type)))
        return cursor.rowcount > 0

    def run_migration(self, migration, migration_type, up):
        """Run ``up()`` unless ``migration`` was already applied; record it
        once ``up`` completes. Return whether it ran."""
        if self.is_migrated(migration, migration_type):
            return False
        up()
        self.add_migration(migration, migration_type)
        return True

    def rollback_migration(self, migration, migration_type, down=None):
        """Run ``down()`` (if given) for an applied migration and remove its
        record. Return whether it was rolled back."""
        if not self.is_migrated(migration, migration_type):
            return False
        if down is not None:
            down()
        self.remove_migration(migration, migration_type)
        return True


class _Transaction:
    def __init__(self, conn):
        self._conn = conn

    def __enter__(self):
        self._conn.execute("BEGIN IMMEDIATE")

    def __exit__(self, exc_type, exc, tb):
        self._conn.execute("COMMIT" if exc_type is None else "ROLLBACK")
        return False


def open_database(root_dir):
    """The database below ``root_dir`` (created on first access)."""
    return Database(db_path(root_dir))

