                return None
        return values.read_value(raw, self.args.option("format"))


def build_tree():
    tree = CommandTree()
    catalog.register_all(tree)
    return tree


def _split_alias(argv):
    """Remove a leading ``@alias`` word; return ``(alias, argv)``."""
    for index, raw in enumerate(argv):
        if raw == "--":
            break
        if raw.startswith("--") and len(raw) > 2:
            continue
        if aliases.is_alias_name(raw):
            return raw, argv[:index] + argv[index + 1:]
        break
    return None, argv


def _is_completion(argv):
    """Tab-completion invocations are never written to the log file."""
    words = []
    for raw in argv:
        if raw == "--":
            break
        if not raw.startswith("--"):
            words.append(raw)
    return words[:len(_COMPLETION)] == _COMPLETION


def _last_option(options, name):
    found = None
    for key, value in options:
        if key == name:
            found = value
    return found


class _Invocation:
    def __init__(self, argv, env, stdout, stderr, tree, cwd, stdin, started):
        self.argv = argv
        self.env = env
        self.stdout = stdout
        self.stderr = stderr
        self.tree = tree
        self.cwd = cwd
        self.stdin = stdin
        self.started = started

    def _color(self, setting):
        return color_enabled(setting, self.stdout)

    def start(self, alias):
        self.locations = config_files.Locations(self.env)
        log = logfile.LogFile(logfile.log_path(self.locations.root_dir),
                              enabled=not _is_completion(self.argv))
        log.start_invocation()
        self.out = out = Output(self.stdout, self.stderr, stdin=self.stdin, log=log,
                                start=self.started, color=self._color("auto"))
        try:
            items = rewrites.apply(tokens.lex(self.argv))
            self.runtime, self.items = runtime_config.extract(items, self.env)
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        runtime_values = self.runtime.values
        out.configure(quiet=self.runtime.quiet(),
                      debug=runtime_values.get("debug", False),
                      color=self._color(runtime_values.get("color", "auto")))
        for warning in self.runtime.warnings:
            out.warning(warning)
        self.cache = file_cache.from_env(self.env, self.locations.root_dir,
                                         warn=out.warning)
        try:
            self.db = db.open_database(self.locations.root_dir)
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        try:
            return self.load_and_execute(alias)
        finally:
            self.db.close()
            if not _is_completion(self.argv):
                try:
                    self.cache.clean()
                except OSError:
                    pass

    def load_and_execute(self, alias):
        out = self.out
        try:
            self.loaded = config_files.load(self.locations, self.cwd)
            if "color" not in self.runtime.values:
                out.configure(color=self._color(self.loaded.values.get("color", "auto")))
            self.registry = aliases.AliasRegistry(
                self.loaded.aliases, aliases.runtime_aliases(self.env))
            for path in self.loaded.files:
                out.debug(f"Loaded config file: {path}", group="bootstrap")
            return self.execute(alias, ())
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        except Halt as exc:
            return exc.exit_code

    def execute(self, alias, stack):
        if alias is None:
            return self.invoke({})
        target = self.registry.resolve(alias)
        if not target.is_group():
            return self.invoke(target.connection)
        code = 0
        for member in target.members:
            if member == alias or member in stack:
                continue
            self.out.log(member)
            try:
                result = self.execute(member, stack + (alias,))
            except CliError as exc:
                self.out.report(exc)
                result = exc.exit_code
            code = result or code
        return code

    def invoke(self, connection):
        config = runtime_config.layer(
            self.runtime, self.loaded.values, connection,
            locations=self.locations, loaded=self.loaded, aliases=self.registry)
        self.out.configure(color=self._color(config.color()))
        if config.ssh():
            return remote.run(config.ssh(), self.argv, connection,
                              self.runtime.values, config, self.env, self.out,
                              self.stdout, self.stderr)
        return self.run_local(config)

    def run_local(self, config):
        out = self.out
        if self.tree is None:
            self.tree = build_tree()
        tree = self.tree
        items = self.items
        words = [t.text for t in items if not t.is_option()] or ["help"]
        options = [(t.name, t.value) for t in items if t.is_option()]
        node = None
        try:
            node, remaining = dispatch.resolve(tree, words, config.disabled_commands())
            out.debug(f"Resolved command '{node.path}' with arguments {remaining}",
                      group="bootstrap")
            out.log_only(f"Command: {node.path}")
            if not node.is_runnable():
                out.usage(help_text.composite_usage(node))
                return 0
            remaining = self.stdin_fallback(node.synopsis, remaining, options)
            bound = binding.bind(node.path, node.synopsis, node.defaults(),
                                 remaining, options)
            launcher = process.Launcher(
                self.runtime.values, self.env, self.cwd, out,
                config_path=self.locations.global_config_path)
            result = node.run(CommandContext(node, bound, out, config, tree,
                                             cwd=self.cwd, cache=self.cache,
                                             launcher=launcher, db=self.db,
                                             env=self.env))
            return int(result or 0)
        except MissingPositional:
            out.usage(help_text.usage_line(node))
            return 1

    def stdin_fallback(self, synopsis, words, options):
        """Read a missing required positional from STDIN, if any is piped."""
        if len(words) >= synopsis.required_positional_count():
            return words
        raw = self.out.read_stdin()
        if raw is None:
            return words
        fmt = (_last_option(options, "format")
               if "format" in synopsis.option_names() else None)
        return list(words) + [values.read_value(raw, fmt)]


def run(argv, env, stdout, stderr, tree=None, cwd=None, stdin=None):
    """Run one invocation and return its exit code.

    ``stdin`` defaults to ``sys.stdin`` at the time input is needed.
    """
    started = time.monotonic()
    alias, argv = _split_alias(list(argv))
    invocation = _Invocation(argv, env, stdout, stderr, tree,
                             cwd if cwd is not None else os.getcwd(), stdin, started)
    return invocation.start(alias)
"""Command resolution.

Secret: how positional words are walked down the command tree, and when
leftover words become arguments of the matched command rather than unknown
subcommands.
"""

from . import messages as _messages
from .errors import CliError
from .suggest import suggest


def resolve(tree, words, disabled=()):
    """Find the deepest command matching the leading ``words``.

    Returns ``(node, remaining_words)``. Raises ``CliError`` for an unknown
    top-level command, an unknown subcommand under a group that cannot
    itself run, or a command whose path is listed in ``disabled``.
    """
    disabled = set(disabled)
    node = tree.root
    words = list(words)
    consumed = 0
    for word in words:
        if not node.has_children():
            break
        child = node.find_child(word)
        if child is None:
            if node.is_runnable() and not node.is_root():
                break
            suggestion = suggest(word, node.child_names())
            if node.is_root():
                raise CliError(_messages.unregistered_command(word, suggestion))
            raise CliError(_messages.unregistered_subcommand(
                word, node.path, suggestion))
        node = child
        consumed += 1
        if node.path in disabled:
            raise CliError(_messages.command_disabled(node.path))
    return node, words[consumed:]
"""Exception types shared by several module interfaces."""


class CliError(Exception):
    """A user-facing failure: the message is reported as an error and the
    process exits with ``exit_code``.

    ``message`` may be a list of lines, which is reported as a multi-line
    error. A ``sensitive`` error contains user-supplied material that must
    never reach the log file; ``log_message`` is an optional redacted form
    that may be logged instead.
    """

    def __init__(self, message, exit_code=1, sensitive=False, log_message=None):
        lines = None
        if isinstance(message, (list, tuple)):
            lines = [str(line) for line in message]
            message = "\n".join(lines)
        super().__init__(message)
        self.message = message
        self.lines = lines
        self.exit_code = exit_code
        self.sensitive = sensitive
        self.log_message = log_message


class MissingPositional(Exception):
    """Raised when a command did not receive all of its required positional
    arguments; the caller is expected to show that command's usage."""


class Halt(Exception):
    """Stops the invocation with ``exit_code`` without reporting anything
    (the cause has already been shown, e.g. by a child process)."""

    def __init__(self, exit_code):
        super().__init__(exit_code)
        self.exit_code = exit_code
"""Persistent state database.

Secret: where the SQLite file lives, the table layout used for key/value
options and for the migration history, the timestamp format, and how
connection and schema failures are reported.
"""

import os
import sqlite3
from datetime import datetime, timezone

from . import messages
from .errors import CliError

_SUBDIR = "db"
_FILE_NAME = "appctl.sqlite"
_TIMESTAMP = "%Y-%m-%dT%H:%M:%SZ"
_BUSY_TIMEOUT = 30

_SCHEMA = (
    """CREATE TABLE IF NOT EXISTS options (
        key TEXT NOT NULL PRIMARY KEY,
        value TEXT NOT NULL,
        modified_on TEXT NOT NULL
    )""",
    """CREATE TABLE IF NOT EXISTS migrations (
        migration TEXT NOT NULL,
        type TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        PRIMARY KEY (migration, type)
    )""",
)


def db_dir(root_dir):
    return os.path.join(root_dir, _SUBDIR)


def db_path(root_dir):
    """``<root_dir>/db/appctl.sqlite``."""
    return os.path.join(db_dir(root_dir), _FILE_NAME)


def timestamp(now=None):
    """UTC timestamp in ISO 8601 form, e.g. ``2026-01-02T03:04:05Z``."""
    now = now or datetime.now(timezone.utc)
    return now.astimezone(timezone.utc).strftime(_TIMESTAMP)


def _details(exc):
    if isinstance(exc, OSError):
        return getattr(exc, "strerror", None) or str(exc)
    return str(exc)


def _text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="surrogateescape")
    if isinstance(value, bool):
        return "true" if value else "false"
    return "" if value is None else str(value)


class Database:
    """Key/value options and migration history kept in a SQLite file.

    The file and its tables are created on first access. Failures raise a
    ``CliError`` carrying the user-facing message.
    """

    def __init__(self, path):
        self.path = str(path)
        self._conn = None
        self._connect()
        self._create_tables()

    # --- setup ------------------------------------------------------------

    def _connect(self):
        try:
            directory = os.path.dirname(self.path)
            if directory and not os.path.isdir(directory):
                os.makedirs(directory, exist_ok=True)
            self._conn = sqlite3.connect(self.path, timeout=_BUSY_TIMEOUT,
                                         isolation_level=None)
        except (OSError, sqlite3.Error) as exc:
            raise CliError(messages.db_connection_failed(_details(exc))) from exc

    def _create_tables(self):
        try:
            with self._transaction():
                for statement in _SCHEMA:
                    self._conn.execute(statement)
        except sqlite3.Error as exc:
            self.close()
            raise CliError(messages.db_table_creation_failed(_details(exc))) from exc

    def _transaction(self):
        return _Transaction(self._conn)

    def close(self):
        if self._conn is not None:
            try:
                self._conn.close()
            except sqlite3.Error:
                pass
            self._conn = None

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()

    # --- options ----------------------------------------------------------

    def get_option(self, key):
        """The stored string for ``key``, or ``False`` when it is not set."""
        row = self._conn.execute("SELECT value FROM options WHERE key = ?",
                                 (_text(key),)).fetchone()
        return False if row is None else _text(row[0])

    def update_option(self, key, value):
        """Insert or replace the value stored under ``key``."""
        with self._transaction():
            self._conn.execute(
                "INSERT INTO options (key, value, modified_on) VALUES (?, ?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value = excluded.value, "
                "modified_on = excluded.modified_on",
                (_text(key), _text(value), timestamp()))
        return True

    def get_options(self):
        """Every option as ``{key, value, modified_on}``, ordered by key."""
        rows = self._conn.execute(
            "SELECT key, value, modified_on FROM options ORDER BY key")
        return [{"key": _text(k), "value": _text(v), "modified_on": _text(m)}
                for k, v, m in rows]

    # --- migrations -------------------------------------------------------

    def get_migrations(self, migration_type=None):
        """Applied migrations as ``{migration, type, timestamp}``, ordered by
        type and then name; optionally only those of ``migration_type``."""
        query = "SELECT migration, type, timestamp FROM migrations"
        params = ()
        if migration_type is not None:
            query += " WHERE type = ?"
            params = (_text(migration_type),)
        query += " ORDER BY type, migration"
        return [{"migration": _text(m), "type": _text(t), "timestamp": _text(s)}
                for m, t, s in self._conn.execute(query, params)]

    def is_migrated(self, migration, migration_type):
        row = self._conn.execute(
            "SELECT 1 FROM migrations WHERE migration = ? AND type = ?",
            (_text(migration), _text(migration_type))).fetchone()
        return row is not None

    def add_migration(self, migration, migration_type):
        """Record ``migration`` as applied now."""
        with self._transaction():
            self._conn.execute(
                "INSERT INTO migrations (migration, type, timestamp) VALUES (?, ?, ?) "
                "ON CONFLICT(migration, type) DO UPDATE SET timestamp = excluded.timestamp",
                (_text(migration), _text(migration_type), timestamp()))
        return True

    def remove_migration(self, migration, migration_type):
        """Forget ``migration``; ``True`` when a record was removed."""
        with self._transaction():
            cursor = self._conn.execute(
                "DELETE FROM migrations WHERE migration = ? AND type = ?",
                (_text(migration), _text(migration_type)))
        return cursor.rowcount > 0

    def run_migration(self, migration, migration_type, up):
        """Run ``up()`` unless ``migration`` was already applied; record it
        once ``up`` completes. Return whether it ran."""
        if self.is_migrated(migration, migration_type):
            return False
        up()
        self.add_migration(migration, migration_type)
        return True

    def rollback_migration(self, migration, migration_type, down=None):
        """Run ``down()`` (if given) for an applied migration and remove its
        record. Return whether it was rolled back."""
        if not self.is_migrated(migration, migration_type):
            return False
        if down is not None:
            down()
        self.remove_migration(migration, migration_type)
        return True


class _Transaction:
    def __init__(self, conn):
        self._conn = conn

    def __enter__(self):
        self._conn.execute("BEGIN IMMEDIATE")

    def __exit__(self, exc_type, exc, tb):
        self._conn.execute("COMMIT" if exc_type is None else "ROLLBACK")
        return False


def open_database(root_dir):
    """The database below ``root_dir`` (created on first access)."""
    return Database(db_path(root_dir))

"""Containers, compose projects, volumes and networks.

Secret: which container runtime binary is driven and with which arguments,
how compose files are discovered and merged, how project-scoped resource
names are derived, which labels mark resources as belonging to appctl, and
how volumes are linked into the host filesystem on each platform.
"""

import glob
import os
import re
import shlex
import shutil
import subprocess
import sys

from . import messages as _messages
from . import process, yaml_lite
from .errors import CliError
from .output import Output

RUNTIME = "docker"
RUNNING = "running"
EXITED = "exited"
VENDOR_LABEL = "org.label-schema.vendor=AppCtl"
PROJECT_LABEL = "io.appctl.project"
DEFAULT_ROOT_DIR = "/var/lib/docker"

# Base compose file names, in order of preference.
BASE_COMPOSE_FILES = ("compose.yaml", "compose.yml",
                      "docker-compose.yaml", "docker-compose.yml")
# Optional overrides discovered in a project directory, in order of application.
OVERRIDE_COMPOSE_FILES = ("compose.override.yaml", "compose.override.yml",
                          "docker-compose.override.yaml", "docker-compose.override.yml",
                          "docker-compose-custom.yaml", "docker-compose-custom.yml")
OVERRIDE_COMPOSE_DIR = "user-docker-compose"
_COMPOSE_EXTENSIONS = (".yml", ".yaml")
# Service keys whose sequence value is replaced, not extended, by an override.
_REPLACED_KEYS = {"command", "entrypoint", "test", "dns", "dns_search"}
_FALSE_WORDS = {"", "0", "false", "no", "off", "none", "null"}


# --- naming -------------------------------------------------------------------

def project_prefix(project):
    """Deterministic, runtime-safe prefix for resources of ``project``."""
    return re.sub(r"[^a-z0-9]", "", str(project).lower())


def volume_name(project, volume):
    """Name of the persistent volume ``volume`` (a spec or a name) of ``project``."""
    name = volume["name"] if isinstance(volume, dict) else volume
    return f"{project_prefix(project)}_{name}"


def project_labels(project):
    return [VENDOR_LABEL, f"{PROJECT_LABEL}={project}"]


def is_truthy(value):
    if isinstance(value, str):
        return value.strip().lower() not in _FALSE_WORDS
    return bool(value)


def is_darwin(platform=None):
    return (platform or sys.platform) == "darwin"


# --- compose files ------------------------------------------------------------

def is_compose_file(path):
    return os.path.isfile(path) and path.lower().endswith(_COMPOSE_EXTENSIONS)


def base_compose_file(project_dir):
    for name in BASE_COMPOSE_FILES:
        candidate = os.path.join(project_dir, name)
        if is_compose_file(candidate):
            return candidate
    return None


def discovered_overrides(project_dir):
    """Optional override files found in ``project_dir``, in application order."""
    found = [os.path.join(project_dir, name) for name in OVERRIDE_COMPOSE_FILES]
    found = [path for path in found if is_compose_file(path)]
    pattern = os.path.join(glob.escape(os.path.join(project_dir, OVERRIDE_COMPOSE_DIR)), "*")
    found += sorted(path for path in glob.glob(pattern) if is_compose_file(path))
    return found


def _resolve_custom(custom, cwd, project_dir):
    path = os.path.expanduser(str(custom))
    if os.path.isabs(path):
        return path
    for base in (cwd, project_dir):
        candidate = os.path.join(base, path)
        if os.path.exists(candidate):
            return os.path.normpath(candidate)
    return os.path.normpath(os.path.join(cwd, path))


def compose_files(project_dir, custom=None, cwd=None, out=None):
    """The compose files of a project: the base file, then the overrides.

    A non-empty ``custom`` path is applied after the base file; otherwise
    overrides are discovered in the project directory. A missing custom file
    is reported as a warning and skipped.
    """
    project_dir = os.path.abspath(project_dir)
    files = []
    base = base_compose_file(project_dir)
    if base:
        files.append(base)
    if custom not in (None, "") and str(custom).strip():
        path = _resolve_custom(custom, cwd or project_dir, project_dir)
        if not os.path.isfile(path):
            (out or _default_output()).warning(_messages.custom_compose_missing(custom))
        elif is_compose_file(path) and path not in files:
            files.append(path)
    else:
        files += [path for path in discovered_overrides(project_dir) if path not in files]
    return files


def _merge_sequence(old, new):
    merged = list(old)
    for item in new:
        if item not in merged:
            merged.append(item)
    return merged


def merge_compose(base, override, key=None):
    """Merge one compose definition into another, as compose does."""
    if isinstance(base, dict) and isinstance(override, dict):
        merged = dict(base)
        for name, value in override.items():
            merged[name] = (merge_compose(merged[name], value, name)
                            if name in merged else value)
        return merged
    if (isinstance(base, list) and isinstance(override, list)
            and key not in _REPLACED_KEYS):
        return _merge_sequence(base, override)
    return override


def load_compose(files):
    """Merged compose definition of ``files``."""
    merged = {}
    for path in files:
        try:
            with open(path, encoding="utf-8") as handle:
                data = yaml_lite.load(handle.read())
        except OSError as exc:
            raise CliError(_messages.compose_unparsable(path, exc)) from None
        except yaml_lite.YamlError as exc:
            raise CliError(_messages.compose_unparsable(path, exc)) from None
        if isinstance(data, dict):
            merged = merge_compose(merged, data)
    return merged


def service_names(definition):
    services = definition.get("services") if isinstance(definition, dict) else None
    return [str(name) for name in services] if isinstance(services, dict) else []


# --- runtime ------------------------------------------------------------------

def _default_output():
    return Output(sys.stdout, sys.stderr)


def _fileno(stream):
    try:
        return stream.fileno()
    except (AttributeError, OSError, ValueError):
        return None


class Runtime:
    """Drives the container runtime on behalf of one invocation.

    ``config`` is anything with a ``get(name, default)`` method (e.g. the
    effective runtime configuration); ``custom-compose`` and ``skip-tty`` are
    read from it.
    """

    def __init__(self, out=None, env=None, cwd=None, config=None, platform=None,
                 stdout=None, stderr=None):
        self.out = out or _default_output()
        self.env = dict(env) if env is not None else dict(os.environ)
        self.cwd = cwd or os.getcwd()
        self.config = config if config is not None else {}
        self.platform = platform
        self.stdout = stdout
        self.stderr = stderr

    # --- plumbing -----------------------------------------------------------

    def _setting(self, name):
        return self.config.get(name, None)

    def is_installed(self):
        return shutil.which(RUNTIME, path=self.env.get("PATH")) is not None

    def ensure_installed(self):
        if not self.is_installed():
            raise CliError(_messages.container_runtime_missing())

    def run(self, args, cwd=None):
        """Run the runtime with ``args``; return the ``ProcessRun``."""
        self.ensure_installed()
        return process.run([RUNTIME] + [str(a) for a in args], cwd=cwd or self.cwd,
                           env=self.env, out=self.out)

    def check(self, args, cwd=None):
        return self.run(args, cwd=cwd).succeeded

    def passthrough(self, args, cwd=None):
        """Run the runtime attached to the terminal; return its exit code."""
        self.ensure_installed()
        argv = [RUNTIME] + [str(a) for a in args]
        self.out.debug(f"Running command: {process.command_text(argv)}", group="process")
        stdout = self.stdout if self.stdout is not None else self.out.stdout
        stderr = self.stderr if self.stderr is not None else self.out.stderr
        for stream in (stdout, stderr):
            if hasattr(stream, "flush"):
                stream.flush()
        out_fd, err_fd = _fileno(stdout), _fileno(stderr)
        try:
            proc = subprocess.run(
                argv, cwd=cwd or self.cwd, env=self.env,
                stdout=out_fd if out_fd is not None else subprocess.PIPE,
                stderr=err_fd if err_fd is not None else subprocess.PIPE)
        except OSError as exc:
            stderr.write(f"{getattr(exc, 'strerror', None) or exc}\n")
            return 127
        if out_fd is None and proc.stdout:
            stdout.write(proc.stdout.decode(errors="replace"))
        if err_fd is None and proc.stderr:
            stderr.write(proc.stderr.decode(errors="replace"))
        return proc.returncode

    # --- containers ---------------------------------------------------------

    def container_status(self, container):
        """``"running"``, ``"exited"`` or ``None`` when there is no such container."""
        result = self.run(["inspect", "--type=container", "-f", "{{.State.Running}}",
                           container])
        if not result.succeeded:
            return None
        return RUNNING if result.stdout.strip().lower() == "true" else EXITED

    def start_container(self, container):
        return self.check(["start", container])

    def stop_container(self, container):
        return self.check(["stop", container])

    def restart_container(self, container):
        return self.check(["restart", container])

    def boot_container(self, container, create=None):
        """Make sure ``container`` runs: start it if exited, create it if
        missing. ``create`` is a callable, a runtime argument list, or a shell
        command string."""
        status = self.container_status(container)
        if status == EXITED:
            return self.start_container(container)
        if status == RUNNING:
            return True
        if create is None:
            return False
        if callable(create):
            return bool(create())
        if isinstance(create, str):
            return process.run(create, cwd=self.cwd, env=self.env, out=self.out).succeeded
        return self.check(create)

    # --- compose ------------------------------------------------------------

    def compose_files(self, project_dir):
        return compose_files(project_dir, self._setting("custom-compose"),
                             cwd=self.cwd, out=self.out)

    def compose_args(self, project_dir, files=None):
        """Runtime arguments selecting the merged compose project."""
        project_dir = os.path.abspath(project_dir)
        if files is None:
            files = self.compose_files(project_dir)
        args = ["compose"]
        prefix = project_prefix(os.path.basename(project_dir))
        if prefix:
            args += ["-p", prefix]
        for path in files:
            args += ["-f", path]
        return args

    def compose_definition(self, project_dir):
        files = self.compose_files(project_dir)
        if not files:
            raise CliError(_messages.no_compose_file(os.path.abspath(project_dir)))
        return load_compose(files)

    def services(self, project_dir):
        """Service names, in the order they appear in the merged configuration."""
        return service_names(self.compose_definition(project_dir))

    def service_exists(self, project_dir, service):
        try:
            return str(service) in self.services(project_dir)
        except CliError:
            return False

    def compose_up(self, project_dir, services=()):
        args = self.compose_args(project_dir) + ["up", "-d"] + [str(s) for s in services or ()]
        return self.run(args, cwd=os.path.abspath(project_dir))

    def compose_down(self, project_dir):
        args = self.compose_args(project_dir) + ["down", "--volumes", "--remove-orphans"]
        return self.run(args, cwd=os.path.abspath(project_dir))

    def exec_args(self, project_dir, service, command, user=None, shell="sh",
                  shell_wrapper=False):
        args = self.compose_args(project_dir) + ["exec"]
        if is_truthy(self._setting("skip-tty")):
            args.append("-T")
        if user:
            args.append(f"--user={user}")
        args.append(str(service))
        if shell_wrapper:
            text = command if isinstance(command, str) else process.command_text(command)
            return args + [shell or "sh", "-c", text]
        if isinstance(command, str):
            return args + shlex.split(command)
        return args + [str(part) for part in command]

    def compose_exec(self, project_dir, service, command, user=None, shell="sh",
                     shell_wrapper=False, interactive=False):
        """Run ``command`` in the container of ``service``. Returns the exit
        code when ``interactive`` (attached to the terminal), otherwise the
        ``ProcessRun``."""
        args = self.exec_args(project_dir, service, command, user=user, shell=shell,
                              shell_wrapper=shell_wrapper)
        cwd = os.path.abspath(project_dir)
        if interactive:
            return self.passthrough(args, cwd=cwd)
        return self.run(args, cwd=cwd)

    # --- volumes ------------------------------------------------------------

    def root_dir(self):
        result = self.run(["info", "--format", "{{.DockerRootDir}}"])
        root = result.stdout.strip() if result.succeeded else ""
        return root or DEFAULT_ROOT_DIR

    def volume_exists(self, name):
        return self.check(["volume", "inspect", name])

    def create_volumes(self, project, volumes):
        """Create the persistent volumes of ``project``; return the names of
        the volumes that were created."""
        created = []
        darwin = is_darwin(self.platform)
        root = None
        for volume in volumes or ():
            if volume.get("skip_volume") is True:
                continue
            name = volume_name(project, volume)
            if self.volume_exists(name):
                continue
            labels = []
            for label in project_labels(project):
                labels += ["--label", label]
            result = self.run(["volume", "create"] + labels + [name])
            if not result.succeeded:
                raise CliError(result.stderr.strip() or f"Unable to create volume '{name}'.")
            created.append(name)
            link = volume.get("path_to_symlink")
            if not link:
                continue
            if darwin:
                if not volume.get("skip_darwin"):
                    os.makedirs(link, exist_ok=True)
            elif not volume.get("skip_linux"):
                if root is None:
                    root = self.root_dir()
                parent = os.path.dirname(link)
                if parent:
                    os.makedirs(parent, exist_ok=True)
                if not os.path.lexists(link):
                    os.symlink(os.path.join(root, "volumes", name, "_data"), link)
        return created

    def mounting_volumes(self, volumes):
        return mounting_volumes(volumes, self.platform)

    # --- networks -----------------------------------------------------------

    def create_network(self, project, name=None):
        args = ["network", "create"]
        for label in project_labels(project):
            args += ["--label", label]
        return self.check(args + [name or project])

    def connect_network(self, network, container):
        if not self.check(["network", "connect", network, container]):
            raise CliError(_messages.network_connect_failed(container))
        self.out.success(_messages.network_connected(container))
        return True

    def disconnect_network(self, network, container):
        if self.check(["network", "disconnect", network, container]):
            self.out.log(_messages.network_disconnected(network, container))
            return True
        self.out.warning(_messages.network_disconnect_failed(container))
        return False

    def remove_network(self, name):
        return self.check(["network", "rm", name])

    def network_exists(self, name):
        return self.check(["network", "inspect", name])


def mounting_volumes(volumes, platform=None):
