"""External command execution.

Secret: how child processes are spawned, timed and logged, how sensitive
substrings are hidden from debug output, the wording of the exit code -1
warning, and how appctl re-invokes itself with the current runtime
configuration.
"""

import json
import os
import shlex
import subprocess
import sys
import time

from . import messages as _messages
from .errors import Halt
from .output import Output

_GROUP = "process"
_MASK = "******"
_SIGNAL_EXIT = -1
_ENTRY_POINT = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "appctl.py")
# Environment variables describing the runtime that a child appctl inherits.
_CONFIG_PATH_ENV = "APPCTL_CONFIG_PATH"


class ProcessRun:
    """Outcome of one external command."""

    def __init__(self, command, stdout, stderr, return_code, run_time, cwd=None, env=None):
        self.command = command
        self.stdout = stdout
        self.stderr = stderr
        self.return_code = return_code
        self.run_time = run_time
        self.cwd = cwd
        self.env = env

    @property
    def succeeded(self):
        return self.return_code == 0

    def __repr__(self):
        return (f"ProcessRun(command={self.command!r}, return_code={self.return_code}, "
                f"run_time={self.run_time:.3f})")


def _default_output():
    return Output(sys.stdout, sys.stderr)


def command_text(command):
    """The command as a single shell-style string."""
    if isinstance(command, (list, tuple)):
        return shlex.join(str(part) for part in command)
    return str(command)


def obfuscate(text, secrets):
    """Replace every listed substring of ``text`` with ``******``."""
    text = str(text)
    for secret in sorted({str(s) for s in secrets or () if s not in (None, "")},
                         key=len, reverse=True):
        text = text.replace(secret, _MASK)
    return text


def _decode(data):
    if data is None:
        return ""
    if isinstance(data, bytes):
        return data.decode(errors="replace")
    return data


def run(command, *, cwd=None, env=None, out=None, obfuscate_list=(), stdin=None):
    """Run ``command`` and return a ``ProcessRun``.

    ``command`` is either a shell command string or an argument list. The
    command is logged at debug level before it runs (with every substring in
    ``obfuscate_list`` masked); afterwards non-empty STDOUT and STDERR and the
    return code are logged. The returned result always holds the real values.
    """
    out = out or _default_output()
    text = command_text(command)

    def debug(message):
        out.debug(obfuscate(message, obfuscate_list), group=_GROUP)

    debug(f"Running command: {text}")
    started = time.monotonic()
    try:
        proc = subprocess.run(
            command, shell=isinstance(command, str), cwd=cwd,
            env=dict(env) if env is not None else None,
            input=stdin.encode() if isinstance(stdin, str) else stdin,
            stdin=None if stdin is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr, code = _decode(proc.stdout), _decode(proc.stderr), proc.returncode
    except OSError as exc:
        stdout, stderr, code = "", f"{getattr(exc, 'strerror', None) or exc}\n", 127
    result = ProcessRun(text, stdout, stderr, code, time.monotonic() - started,
                        cwd=cwd, env=env)
    if stdout:
        debug(f"STDOUT: {stdout.rstrip(chr(10))}")
    if stderr:
        debug(f"STDERR: {stderr.rstrip(chr(10))}")
    debug(f"Return code: {code}")
    if code == _SIGNAL_EXIT:
        out.warning(_messages.spawned_exit_minus_one())
    return result


def run_check(command, **kwargs):
    """Run ``command`` and return whether it exited successfully."""
    return run(command, **kwargs).succeeded


# --- re-dispatching appctl -------------------------------------------------

def _flag(name, value):
    if value is True:
        return f"--{name}"
    if value is False:
        return f"--no-{name}" if name == "color" else None
    if value is None:
        return None
    return f"--{name}={value}"


def runtime_flags(runtime_values):
    """Global flags reproducing ``runtime_values`` on a command line."""
    flags = []
    for name, value in runtime_values.items():
        flag = _flag(name, value)
        if flag is not None:
            flags.append(flag)
    return flags


def _args_list(command):
    if isinstance(command, str):
        return shlex.split(command)
    return [str(part) for part in command]


def _assoc_flags(assoc_args):
    flags = []
    for key, value in (assoc_args or {}).items():
        flag = _flag(key, value)
        if flag is not None:
            flags.append(flag)
    return flags


class Launcher:
    """Runs appctl as a child process with the current runtime configuration:
    the same interpreter and entry point, the same global flags, config file
    path, environment and working directory."""

    def __init__(self, runtime_values, env, cwd, out, config_path=None):
        self.runtime_values = dict(runtime_values or {})
        self.env = dict(env or {})
        self.cwd = cwd
        self.out = out or _default_output()
        self.config_path = config_path

    def argv(self, command, args=(), assoc_args=None, runtime_args=None):
        values = dict(self.runtime_values)
        values.update(runtime_args or {})
        return ([sys.executable, _ENTRY_POINT] + runtime_flags(values)
                + _args_list(command) + [str(a) for a in args]
                + _assoc_flags(assoc_args))

    def environment(self):
        env = dict(self.env)
        if self.config_path and not env.get(_CONFIG_PATH_ENV):
            env[_CONFIG_PATH_ENV] = self.config_path
        return env

    def launch(self, command, args=(), assoc_args=None, *, runtime_args=None,
               obfuscate_list=(), stdin=None):
        """Run appctl ``command`` and return the ``ProcessRun``."""
        return run(self.argv(command, args, assoc_args, runtime_args),
                   cwd=self.cwd, env=self.environment(), out=self.out,
                   obfuscate_list=obfuscate_list, stdin=stdin)

    def launch_self(self, command, args=(), assoc_args=None, *, exit_on_error=True,
                    return_detailed=False, runtime_args=None, obfuscate_list=()):
        """Run appctl ``command``; return the ``ProcessRun`` when
        ``return_detailed`` or else its return code. A failure halts the
        current invocation with the same code when ``exit_on_error``."""
        result = self.launch(command, args, assoc_args, runtime_args=runtime_args,
                             obfuscate_list=obfuscate_list)
        if return_detailed:
            return result
        if result.return_code and exit_on_error:
            raise Halt(result.return_code)
        return result.return_code

    def runcommand(self, command, *, return_="stdout", parse=None, exit_error=True,
                   obfuscate_list=(), stdin=None):
        """Run appctl ``command`` and return part of its outcome.

        ``return_`` is ``"stdout"``, ``"stderr"``, ``"return_code"`` or
        ``"all"``; with ``parse="json"`` STDOUT is decoded as JSON (``None``
        when it is not valid JSON).
        """
        result = self.launch(command, obfuscate_list=obfuscate_list, stdin=stdin)
        if result.return_code and exit_error:
            if result.stderr:
                self.out.write_stderr(result.stderr)
            raise Halt(result.return_code)
        if return_ == "all":
            return result
        if return_ == "return_code":
            return result.return_code
        if return_ == "stderr":
            return result.stderr.rstrip("\r\n")
        stdout = result.stdout.rstrip("\r\n")
        if parse == "json":
            try:
                return json.loads(stdout)
            except ValueError:
                return None
        return stdout
"""Configuration sources.

Secret: where the global and project config files live, how YAML
inheritance (``_: {inherit, merge}``) and array merging work, how alias
definitions are collected from files, and how missing global defaults are
written back to the global config file.
"""

import errno
import os

from . import config_spec, messages, yaml_lite
from .aliases import is_alias_name
from .errors import CliError

_PROJECT_FILES = ("appctl.local.yml", "appctl.yml")
_AUTO_DEFAULTS = (("locale", "en_US"), ("installer_version", "stable"))
_META_KEY = "_"


class Locations:
    """Filesystem locations derived from the environment."""

    def __init__(self, env):
        root = env.get("APPCTL_ROOT_DIR") or ""
        config = env.get("APPCTL_CONFIG_PATH") or ""
        self.explicit = bool(root or config)
        if not root:
            home = env.get("HOME") or os.path.expanduser("~")
            root = os.path.join(home, ".appctl")
        self.root_dir = _clean(root)
        self.global_config_path = (_clean(config) if config else
                                   os.path.join(self.root_dir, "config", "config.yml"))
        packages = env.get("APPCTL_PACKAGES_DIR") or ""
        self.packages_dir = (_clean(packages) if packages else
                             os.path.join(self.root_dir, "packages"))


def _clean(path):
    path = os.path.expanduser(path)
    stripped = path.rstrip(os.sep)
    return stripped or path


def find_project_config(cwd):
    """Search upward from ``cwd`` for a project config file."""
    directory = os.path.abspath(cwd)
    while True:
        for name in _PROJECT_FILES:
            candidate = os.path.join(directory, name)
            if os.path.isfile(candidate):
                return candidate
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


def _absolutize(path, base):
    path = os.path.expanduser(path)
    if os.path.isabs(path):
        return path
    return os.path.normpath(os.path.join(base, path))


def _arrayify(value):
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return list(value)
    return [value]


def _combine(old, new, merge):
    if merge and isinstance(old, list) and isinstance(new, list):
        return old + new
    return new


def _parse(path, text):
    try:
        data = yaml_lite.load(text)
    except yaml_lite.YamlError as exc:
        raise CliError(messages.config_unparsable(path, exc)) from None
    return data if isinstance(data, dict) else ({} if data is None else None)


def _read(path, tolerant=False):
    """Return the mapping stored at ``path`` or ``None`` if absent."""
    if not os.path.exists(path):
        return None
    try:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        if tolerant:
            return None
        raise CliError(messages.config_unreadable(path, exc)) from None
    data = _parse(path, text)
    return {} if data is None else data


class LoadedConfig:
    """Values, aliases and other keys collected from config files."""

    def __init__(self):
        self.values = {}
        self.aliases = {}
        self.extra = {}
        self.global_config_path = None
        self.project_config_path = None
        self.files = []

    def merge_file(self, path, tolerant=False, chain=()):
        real = os.path.realpath(path)
        if real in chain:
            return
        data = _read(path, tolerant)
        if data is None:
            return
        meta = data.get(_META_KEY)
        meta = meta if isinstance(meta, dict) else {}
        base = os.path.dirname(os.path.abspath(path))
        inherit = meta.get("inherit")
        if isinstance(inherit, str) and inherit:
            self.merge_file(_inherit_path(inherit, base), tolerant, chain + (real,))
        merge = bool(meta.get("merge"))
        self.files.append(path)
        for key, value in data.items():
            if key == _META_KEY:
                continue
            key = str(key)
            if is_alias_name(key):
                self._merge_alias(key, value, base, merge)
            elif config_spec.file_param(key) is not None:
                self._merge_param(key, value, base, merge)
            else:
                self.extra[key] = _combine(self.extra.get(key), value, merge)

    def _merge_alias(self, name, value, base, merge):
        if isinstance(value, list):
            definition = [str(v) for v in value if v is not None]
        elif isinstance(value, dict):
            definition = {str(k): v for k, v in value.items()}
            path = definition.get("path")
            if isinstance(path, str) and path and "ssh" not in definition:
                definition["path"] = _absolutize(path, base)
        elif value is None:
            definition = {}
        else:
            return
        self.aliases[name] = _combine(self.aliases.get(name), definition, merge)

    def _merge_param(self, key, value, base, merge):
        param = config_spec.file_param(key)
        if param.kind == "list":
            value = _arrayify(value)
        if key == "path" and isinstance(value, str) and value:
            value = _absolutize(value, base)
        self.values[key] = _combine(self.values.get(key), value, merge)


def _inherit_path(inherit, base):
    inherit = os.path.expanduser(inherit)
    if os.path.isabs(inherit):
        return inherit
    relative = os.path.join(base, inherit)
    if not os.path.exists(relative) and os.path.exists(inherit):
        return os.path.abspath(inherit)
    return os.path.normpath(relative)


def ensure_global_defaults(locations):
    """Write missing auto-created keys into the global config file."""
    path = locations.global_config_path
    try:
        text = ""
        if os.path.exists(path):
            if not os.path.isfile(path):
                raise IsADirectoryError(errno.EISDIR, os.strerror(errno.EISDIR), path)
            with open(path, encoding="utf-8") as handle:
                text = handle.read()
        data = _parse(path, text)
        if data is None:
            return
        missing = [(k, v) for k, v in _AUTO_DEFAULTS if k not in data]
        if not missing:
            return
        expected = dict(data, **dict(missing))
        separator = "\n" if text and not text.endswith("\n") else ""
        updated = text + separator + "".join(
            yaml_lite.scalar_line(k, v) for k, v in missing)
        try:
            if yaml_lite.load(updated) != expected:
                raise yaml_lite.YamlError("append changed meaning")
        except yaml_lite.YamlError:
            updated = yaml_lite.dump(expected)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(updated)
    except OSError as exc:
        if locations.explicit:
            raise CliError(messages.config_unwritable(path, exc)) from None


def load(locations, cwd):
    """Load the global config file then the project config file."""
    loaded = LoadedConfig()
    ensure_global_defaults(locations)
    global_path = locations.global_config_path
    if os.path.isfile(global_path):
        loaded.global_config_path = global_path
        loaded.merge_file(global_path, tolerant=not locations.explicit)
    project = find_project_config(cwd)
    if project and not (loaded.global_config_path and
                        os.path.realpath(project) == os.path.realpath(global_path)):
        loaded.project_config_path = project
        loaded.merge_file(project)
    return loaded

